#[derive(Debug, Clone, Copy, PartialEq, Eq)]
enum Outcome {
    Forwarded,
    Rejected,
}

struct Req {
    label: String,
    path: &'static str,
    user: Address,
    delegator: Option<Address>,
    expect: Outcome,
    /// ACL view expected to return false on every attempt (checked from the recording), or `-`.
    expect_false: &'static str,
}

impl Req {
    fn direct(label: String, user: Address, expect: Outcome, expect_false: &'static str) -> Self {
        Self {
            label,
            path: "direct",
            user,
            delegator: None,
            expect,
            expect_false,
        }
    }

    fn delegated(
        label: String,
        delegate: Address,
        delegator: Address,
        expect: Outcome,
        expect_false: &'static str,
    ) -> Self {
        Self {
            label,
            path: "delegated",
            user: delegate,
            delegator: Some(delegator),
            expect,
            expect_false,
        }
    }
}

struct RunCfg {
    max_attempts: u16,
    fast_polling: Duration,
    late_wait: Duration,
    outcome_timeout: Duration,
}

impl RunCfg {
    /// As `tests/acl.rs` and the baseline harness: 3 attempts, 500 ms DB polling.
    fn harness() -> Self {
        Self {
            max_attempts: 3,
            fast_polling: Duration::from_millis(500),
            late_wait: Duration::from_secs(2),
            outcome_timeout: Duration::from_secs(90),
        }
    }

    fn latency() -> Self {
        Self {
            late_wait: Duration::from_millis(500),
            ..Self::harness()
        }
    }

    /// The connector's own defaults (`Config::default()`): attempts and DB polling not overridden.
    fn production_defaults() -> Self {
        let d = Config::default();
        Self {
            max_attempts: d.max_decryption_attempts,
            fast_polling: d.db_fast_event_polling,
            late_wait: Duration::from_secs(2),
            outcome_timeout: Duration::from_secs(200),
        }
    }
}

struct RunResult {
    label: String,
    expected: Outcome,
    observed: Outcome,
    kms_hits: usize,
    s3_hits: usize,
    error_counter: Option<i16>,
}

