/// KMS Core mock (same mocks as tests/integration_tests.rs), bound to 127.0.0.1, one per request. It
/// accepts anything: a rejected request must fail before reaching it.
async fn start_kms_mock() -> anyhow::Result<MockServer> {
    let mut kms_mocks = MockSet::new();
    kms_mocks.mock(|when, then| {
        when.path("/kms_service.v1.CoreServiceEndpoint/UserDecrypt");
        then.pb(Empty::default());
    });
    kms_mocks.mock(|when, then| {
        when.path("/kms_service.v1.CoreServiceEndpoint/GetUserDecryptionResult");
        then.pb(UserDecryptionResponse {
            payload: Some(UserDecryptionResponsePayload::default()),
            ..Default::default()
        });
    });
    let kms_server = MockServer::new_grpc("kms_service.v1.CoreServiceEndpoint")
        .with_config(localhost_mock_config())
        .with_mocks(kms_mocks);
    kms_server.start().await?;
    Ok(kms_server)
}

async fn wait_for_outcome(
    db: &Pool<Postgres>,
    decryption_id: U256,
    timeout: Duration,
) -> anyhow::Result<Outcome> {
    let start = Instant::now();
    loop {
        let responses: i64 = sqlx::query_scalar(
            "SELECT COUNT(*) FROM user_decryption_responses WHERE decryption_id = $1",
        )
        .bind(decryption_id.as_le_slice())
        .fetch_one(db)
        .await?;
        if responses > 0 {
            return Ok(Outcome::Forwarded);
        }
        let status: Option<String> = sqlx::query_scalar(
            "SELECT status::text FROM user_decryption_requests WHERE decryption_id = $1",
        )
        .bind(decryption_id.as_le_slice())
        .fetch_optional(db)
        .await?;
        if status.as_deref() == Some("failed") {
            return Ok(Outcome::Rejected);
        }
        if start.elapsed() > timeout {
            bail!("timeout waiting for outcome (status={status:?})");
        }
        tokio::time::sleep(Duration::from_millis(100)).await;
    }
}

fn fmt_opt(a: Option<Address>) -> String {
    a.map(|a| a.to_string()).unwrap_or_else(|| "-".to_string())
}

/// Per-test request machinery: one S3 object and one coprocessor for the whole test (the connector's
/// process-global S3 bucket-URL cache is filled by the first forwarded request), one fresh gateway mock,
/// KMS mock and kms-worker per request.
struct RequestHarness<'a> {
    env: &'a Env,
    acl: &'a AnvilAcl,
    kind: AclKind,
    handle: B256,
    s3_server: MockServer,
    s3_bucket_url: String,
    digest: B256,
    copro: Address,
    s3_cache_primed: bool,
}

impl<'a> RequestHarness<'a> {
    async fn new(env: &'a Env, acl: &'a AnvilAcl, kind: AclKind, handle: B256) -> anyhow::Result<Self> {
        let ciphertext = [rand_digest().0, rand_digest().0].concat();
        let digest = keccak256(&ciphertext);
        let mut s3_mocks = MockSet::new();
        let ct_path = format!("/ct128/{}", hex::encode(digest));
        let ct_body = ciphertext.clone();
        s3_mocks.mock(move |when, then| {
            when.get().path(ct_path);
            then.headers([("x-amz-meta-Ct-Format", "compressed_on_cpu")])
                .bytes(ct_body);
        });
        let s3_server = MockServer::new_http("s3")
            .with_config(localhost_mock_config())
            .with_mocks(s3_mocks);
        s3_server.start().await?;
        let s3_bucket_url = format!("http://127.0.0.1:{}/ct128", s3_server.port().unwrap());
        Ok(Self {
            env,
            acl,
            kind,
            handle,
            s3_server,
            s3_bucket_url,
            digest,
            copro: rand_address(),
            s3_cache_primed: false,
        })
    }

    async fn run(
        &mut self,
        db: &Pool<Postgres>,
        req: &Req,
        cfg: &RunCfg,
    ) -> anyhow::Result<RunResult> {
        let c = self.acl.dapp;
        let pairs = vec![CtHandleContractPair {
            ctHandle: self.handle,
            contractAddress: c,
        }];
        let contracts_info = ContractsInfo {
            chainId: U256::from(self.env.chain_id),
            addresses: vec![c],
        };
        let calldata = match req.delegator {
            None => userDecryptionRequestCall {
                ctHandleContractPairs: pairs,
                contractsInfo: contracts_info,
                userAddress: req.user,
                ..Default::default()
            }
            .abi_encode(),
            Some(delegator) => delegatedUserDecryptionRequestCall {
                ctHandleContractPairs: pairs,
                delegationAccounts: DelegationAccounts {
                    delegatorAddress: delegator,
                    delegateAddress: req.user,
                },
                contractsInfo: contracts_info,
                ..Default::default()
            }
            .abi_encode(),
        };

        // Neutral gateway mock: enough for a forward AND for `max_attempts` rejections.
        let tx_hash = rand_digest();
        let asserter = Asserter::new();
        let mut queued = 0u16;
        if !self.s3_cache_primed {
            asserter.push_success(&mock_gateway_tx(tx_hash, calldata.clone())?);
            asserter.push_success(
                &Coprocessor {
                    s3BucketUrl: self.s3_bucket_url.clone(),
                    ..Default::default()
                }
                .abi_encode(),
            );
            queued = 1;
        }
        while queued < cfg.max_attempts {
            asserter.push_success(&mock_gateway_tx(tx_hash, calldata.clone())?);
            queued += 1;
        }
        let gateway_mock_provider = ProviderBuilder::new()
            .disable_recommended_fillers()
            .connect_mocked_client(asserter);
        let kms_server = start_kms_mock().await?;

        // ------------------------------------------------------------ unmodified kms-worker
        let config = Config {
            kms_core_endpoints: vec![kms_server.base_url().unwrap().to_string()],
            max_decryption_attempts: cfg.max_attempts,
            db_fast_event_polling: cfg.fast_polling,
            ..Default::default()
        };
        let host_url = self.env.tagged_host_url(&req.label)?;
        let acl_contracts =
            init_host_chains_acl_contracts_anvil(self.env.chain_id, self.acl.acl, host_url);
        let kms_worker = init_kms_worker(config, gateway_mock_provider, acl_contracts, db).await?;

        let sns_ct = SnsCiphertextMaterial {
            keyId: rand_u256(),
            ctHandle: self.handle,
            snsCiphertextDigest: self.digest,
            coprocessorTxSenderAddresses: vec![self.copro],
        };
        let request = insert_rand_request(
            db,
            EventType::UserDecryptionRequest,
            InsertRequestOptions::new()
                .with_sns_ct_materials(vec![sns_ct])
                .with_tx_hash(tx_hash),
        )
        .await?;
        let ProtocolEventKind::UserDecryption(request) = request else {
            bail!("unexpected request kind");
        };
        // The gateway event's userAddress is the requester (direct) or the delegate (delegated).
        sqlx::query("UPDATE user_decryption_requests SET user_address = $1 WHERE decryption_id = $2")
            .bind(req.user.as_slice())
            .bind(request.decryptionId.as_le_slice())
            .execute(db)
            .await?;
        let id = request.decryptionId;
        info!(
            "L0-REQUEST label={} version={VERSION} acl_kind={} acl={} acl_version=\"{}\" path={} source=onchain \
            user={} delegator={} contract={c} handle={} decryption_id={id} decryption_id_hex={} expected={:?} \
            expect_false={} max_attempts={} fast_polling_ms={}",
            req.label,
            self.kind.slug(),
            self.acl.acl,
            self.acl.version,
            req.path,
            req.user,
            fmt_opt(req.delegator),
            self.handle,
            B256::from(id.to_be_bytes::<32>()),
            req.expect,
            req.expect_false,
            cfg.max_attempts,
            cfg.fast_polling.as_millis(),
        );

        let s3_before = total_hits(&self.s3_server);
        let cancel_token = CancellationToken::new();
        let started = Instant::now();
        let kms_worker_task = tokio::spawn(kms_worker.start(cancel_token.clone()));
        let outcome = wait_for_outcome(db, id, cfg.outcome_timeout).await;
        let wall = started.elapsed();
        if matches!(outcome, Ok(Outcome::Rejected)) {
            // Give a late (wrong) forward a chance to show up before asserting it never happened.
            tokio::time::sleep(cfg.late_wait).await;
        }
        let kms_hits = total_hits(&kms_server);
        let s3_hits = total_hits(&self.s3_server).saturating_sub(s3_before);
        cancel_token.cancel();
        kms_worker_task
            .await
            .map_err(|e| anyhow!("kms-worker task: {e}"))?;
        let observed = outcome?;
        if observed == Outcome::Forwarded {
            self.s3_cache_primed = true;
        }
        let row: Option<(i16, String)> = sqlx::query_as::<_, (i16, String)>(
            "SELECT error_counter, status::text FROM user_decryption_requests WHERE decryption_id = $1",
        )
        .bind(id.as_le_slice())
        .fetch_optional(db)
        .await?;
        let error_counter = row.as_ref().map(|r| r.0);
        info!(
            "L0-RESULT label={} expected={:?} observed={observed:?} kms_mock_hits={kms_hits} s3_mock_hits={s3_hits} \
            error_counter={} status={} harness_wall_ms={}",
            req.label,
            req.expect,
            error_counter.map(|e| e.to_string()).unwrap_or_else(|| "-".into()),
            row.as_ref().map(|r| r.1.clone()).unwrap_or_else(|| "-".into()),
            wall.as_millis(),
        );
        Ok(RunResult {
            label: req.label.clone(),
            expected: req.expect,
            observed,
            kms_hits,
            s3_hits,
            error_counter,
        })
    }
}

/// Outcome assertions. Forwarded: response stored after UserDecrypt + GetUserDecryptionResult at the KMS
/// mock. Rejected: `failed` after `max_attempts` attempts, 0 KMS-mock hits, 0 S3 hits (v0.13.8 checks
/// before fetching).
fn check(r: &RunResult, cfg: &RunCfg) -> anyhow::Result<()> {
    match r.expected {
        Outcome::Forwarded => {
            ensure!(
                r.observed == Outcome::Forwarded,
                "{}: expected Forwarded, observed {:?}",
                r.label,
                r.observed
            );
            ensure!(r.kms_hits >= 2, "{}: UserDecrypt + GetUserDecryptionResult expected", r.label);
        }
        Outcome::Rejected => {
            ensure!(
                r.observed == Outcome::Rejected,
                "{}: expected Rejected, observed {:?} (G2-mock: a retired account must be rejected)",
                r.label,
                r.observed
            );
            ensure!(r.kms_hits == 0, "{}: a rejected request reached the KMS Core", r.label);
            ensure!(r.s3_hits == 0, "{}: a rejected request fetched ciphertexts", r.label);
            ensure!(
                r.error_counter == Some(cfg.max_attempts as i16),
                "{}: error_counter {:?} != max_attempts {}",
                r.label,
                r.error_counter,
                cfg.max_attempts
            );
        }
    }
    Ok(())
}

fn init_tracing() -> tracing::subscriber::DefaultGuard {
    tracing::subscriber::set_default(
        tracing_subscriber::fmt()
            .with_env_filter(
                EnvFilter::try_from_default_env().unwrap_or_else(|_| EnvFilter::new("info")),
            )
            .with_test_writer()
            .finish(),
    )
}

// ================================================================================================
// Level 2 (E1): the successor reads through the unmodified connector's delegated path
// ================================================================================================

/// Latest block timestamp of the anvil chain.
async fn chain_now(acl: &AnvilAcl) -> anyhow::Result<u64> {
    let block: serde_json::Value = acl
        .provider
        .raw_request("eth_getBlockByNumber".into(), ("latest", false))
        .await?;
    let ts = block["timestamp"]
        .as_str()
        .ok_or_else(|| anyhow!("latest block has no timestamp"))?;
    Ok(u64::from_str_radix(ts.trim_start_matches("0x"), 16)?)
}

async fn increase_time(acl: &AnvilAcl, seconds: u64) -> anyhow::Result<()> {
    let _: serde_json::Value = acl
        .provider
        .raw_request("evm_increaseTime".into(), (seconds,))
        .await?;
    let _: serde_json::Value = acl
        .provider
        .raw_request("evm_mine".into(), Vec::<u64>::new())
        .await?;
    Ok(())
}

/// The E1 lifecycle with anvil EOAs: `account` designates, `successor` accepts (its own tx), 7 days pass on the
/// chain, `account` confirms. Checked with `successorOf` (direct read, not recorded).
async fn confirm_successor(acl: &AnvilAcl, account: Address, successor: Address) -> anyhow::Result<()> {
    let e1 = IAclSuccession::new(acl.acl, &acl.provider);
    ensure_success(
        e1.designateSuccessor(successor).from(account).send().await?.get_receipt().await?,
        "designateSuccessor",
    )?;
    ensure_success(
        e1.acceptSuccession(account).from(successor).send().await?.get_receipt().await?,
        "acceptSuccession",
    )?;
    increase_time(acl, 7 * 86_400).await?;
    ensure_success(
        e1.confirmSuccessor().from(account).send().await?.get_receipt().await?,
        "confirmSuccessor",
    )?;
    let confirmed = e1.successorOf(account).call().await?;
    info!("L2-SUCCESSION account={account} successor={successor} successorOf={confirmed} (designate, accept, +7d, confirm)");
    ensure!(confirmed == successor, "successor not confirmed");
    Ok(())
}

async fn resign(acl: &AnvilAcl, account: Address, successor: Address) -> anyhow::Result<()> {
    ensure_success(
        IAclSuccession::new(acl.acl, &acl.provider)
            .resignSuccession(account)
            .from(successor)
            .send()
            .await?
            .get_receipt()
            .await?,
        "resignSuccession",
    )?;
    let now = IAclSuccession::new(acl.acl, &acl.provider).successorOf(account).call().await?;
    info!("L2-RESIGN account={account} successor={successor} successorOf={now}");
    ensure!(now == Address::ZERO, "resignation not effective");
    Ok(())
}

/// Direct (non-recorded) reads, logged as `L2-STATE[tag]`.
async fn log_l2_state(acl: &AnvilAcl, a: &Accounts, handle: B256, tag: &str) -> anyhow::Result<()> {
    let view = acl.instance();
    let c = acl.dapp;
    info!(
        "L2-STATE[{tag}] isAccountRetired(U)={} successorOf(U)={} isHandleDelegatedForUserDecryption(U,S,C,h)={} \
        isHandleDelegatedForUserDecryption(U,D,C,h)={} isAllowed(h,S)={} isAllowed(h,U)={}",
        IAclLevel0::new(acl.acl, &acl.provider).isAccountRetired(a.u).call().await?,
        IAclSuccession::new(acl.acl, &acl.provider).successorOf(a.u).call().await?,
        view.isHandleDelegatedForUserDecryption(a.u, a.s, c, handle).call().await?,
        view.isHandleDelegatedForUserDecryption(a.u, a.d, c, handle).call().await?,
        view.isAllowed(handle, a.s).call().await?,
        view.isAllowed(handle, a.u).call().await?,
    );
    Ok(())
}

/// U (delegator) confirms S as its successor; D holds a live 30-day delegation from U. Before U retires the
/// succession gives S nothing; after it, the unmodified connector forwards S's delegated request (the view answers as
/// an active wildcard delegation) and refuses D's, and S has no use right of its own. A handle granted to U after
/// retirement (straggler) is readable by S. After S resigns, S is refused again.
/// Order: each RequestHarness's first request is a forward (v0.13.8 primes its coprocessor-config cache with it).
#[rstest]
#[timeout(Duration::from_secs(300))]
#[tokio::test]
async fn level2_successor_legacy_delegated() -> anyhow::Result<()> {
    let log_guard = init_tracing();
    let env = Env::load()?;
    let a = Accounts::load(&env).await?;
    let case = "l2.legacy";
    info!("L0-CASE name={case} version={VERSION} acl_kind=level2");
    let acl = deploy_acl(&env, AclKind::Level0, a.owner).await?;
    let h = make_handle(env.chain_id);
    let h2 = make_handle(env.chain_id);
    acl.grant(h, a.u).await?;
    acl.grant(h2, a.v).await?;
    let exp = chain_now(&acl).await? + 30 * 86_400;
    acl.delegate(a.u, a.d, acl.dapp, exp).await?;
    confirm_successor(&acl, a.u, a.s).await?;
    log_l2_state(&acl, &a, h, &format!("{case}.confirmed")).await?;

    let test_instance = TestInstanceBuilder::default()
        .with_tracing(Some(log_guard))
        .with_db(DbInstance::setup().await?)
        .build();
    let db = test_instance.db();
    let mut rh = RequestHarness::new(&env, &acl, AclKind::Level0, h).await?;
    let mut rh2 = RequestHarness::new(&env, &acl, AclKind::Level0, h2).await?;
    let cfg = RunCfg::harness();

    // U active.
    let r = rh
        .run(db, &Req::delegated(format!("{case}.delegate-d.u-active"), a.d, a.u, Outcome::Forwarded, "-"), &cfg)
        .await?;
    check(&r, &cfg)?;
    let r = rh
        .run(
            db,
            &Req::delegated(
                format!("{case}.successor-s.u-active"),
                a.s,
                a.u,
                Outcome::Rejected,
                "isHandleDelegatedForUserDecryption(U,S,C,h)",
            ),
            &cfg,
        )
        .await?;
    check(&r, &cfg)?;

    // U retires: the successor reads, every other delegate is refused, the successor has no use right.
    retire(&acl, a.u, "delegator-with-successor", case).await?;
    log_l2_state(&acl, &a, h, &format!("{case}.u-retired")).await?;
    let r = rh
        .run(db, &Req::delegated(format!("{case}.successor-s.u-retired"), a.s, a.u, Outcome::Forwarded, "-"), &cfg)
        .await?;
    check(&r, &cfg)?;
    let r = rh
        .run(
            db,
            &Req::delegated(
                format!("{case}.delegate-d.u-retired"),
                a.d,
                a.u,
                Outcome::Rejected,
                "isHandleDelegatedForUserDecryption(U,D,C,h)",
            ),
            &cfg,
        )
        .await?;
    check(&r, &cfg)?;
    let r = rh
        .run(db, &Req::direct(format!("{case}.successor-s-direct.u-retired"), a.s, Outcome::Rejected, "isAllowed(h,S)"), &cfg)
        .await?;
    check(&r, &cfg)?;

    // Straggler: C grants h2 to the retired U (inert for U itself), and S reads it.
    acl.grant(h2, a.u).await?;
    let r = rh2
        .run(db, &Req::direct(format!("{case}.h2-holder-v"), a.v, Outcome::Forwarded, "-"), &cfg)
        .await?;
    check(&r, &cfg)?;
    let r = rh2
        .run(db, &Req::delegated(format!("{case}.successor-s.straggler-h2"), a.s, a.u, Outcome::Forwarded, "-"), &cfg)
        .await?;
    check(&r, &cfg)?;

    // S resigns: refused again.
    resign(&acl, a.u, a.s).await?;
    let r = rh
        .run(
            db,
            &Req::delegated(
                format!("{case}.successor-s.after-resign"),
                a.s,
                a.u,
                Outcome::Rejected,
                "isHandleDelegatedForUserDecryption(U,S,C,h)",
            ),
            &cfg,
        )
        .await?;
    check(&r, &cfg)?;
    Ok(())
}
